// =====================================================================
// 3DCRT+ — a flexible retro-screen post-processing toolkit for GDevelop 3D
// Author: Twillion
// Core scan-line shader ported from Timothy Lottes' PUBLIC DOMAIN CRT
// shader ("Please take and use, change, or whatever.").
//
// ---------------------------------------------------------------------
// WHAT THIS IS
// ---------------------------------------------------------------------
// Every 3D layer in GDevelop owns a THREE EffectComposer, built as
// RenderPass -> [SMAAPass] -> OutputPass. This module inserts ONE more pass
// into the target layer's chain: a full-screen shader that redraws the
// rendered scene (scanlines, shadow mask, screen curvature/bulge, chromatic
// aberration, roll, interlacing, bloom, camera blur/pixelation, color
// grading, a black bezel border, and a master OPACITY that blends the whole
// thing against the untouched image).
//
// Since 0.8.0 this is a real post-processing pass rather than an override of
// THREE.WebGLRenderer.render(). The override sat on the SHARED renderer, so
// it ran for every 3D layer and every scene -- which is why it fought with
// GDevelop's own 3D layer effects and why two 3D layers overwrote each
// other. A pass reaches one layer's composer and nothing else.
//
// This file is the ENGINE. It is driven two ways, both of which write to
// the same shared `settings` object so they never fight:
//   1. The behavior (editor-tunable properties), and
//   2. The extension's actions / conditions / expressions (runtime).
//
// NOTE ON SCALES: the public actions/behavior expose friendly numbers
// (opacity 0-255, scanline THICKNESS / pixel SHARPNESS where bigger =
// more, border 0-45, flicker 0-20, bloom 0-100, mask dark 0-100). The
// conversions to the shader's internal values (e.g. the negative
// hardScan/hardPix, the 0-1 fractions) happen in the setters below, so
// the `settings` object and the shader still use the raw internal units.
//
// ---------------------------------------------------------------------
// VERIFIED GDevelop API (checked against GDJS source / forum, 2025-2026)
// ---------------------------------------------------------------------
// Verified against the shipped GDJS runtime of GDevelop 5.6.279
// (Three r160, PIXI 7.4.2):
//   runtimeScene.getGame().getRenderer().getThreeRenderer()    -> THREE.WebGLRenderer
//   runtimeScene.getLayer(name).getRenderer().getThreeCamera() -> THREE.Camera
//   runtimeScene.getLayer(name).getRenderer().getThreeScene()  -> THREE.Scene
//   layerRenderer.addPostProcessingPass(pass)    <- the supported hook
//   layerRenderer.removePostProcessingPass(pass)
//   THREE_ADDONS.ShaderPass                      <- global, UMD
//
// addPostProcessingPass IS the public hook, and GDevelop's own 3D effects
// use it (Scene3D::BrightnessAndContrast, Bloom, Exposure, HueAndSaturation
// in Runtime/Extensions/3D/). Earlier versions of this file claimed no such
// hook existed; that is no longer true.
//
// Two private touches remain, both in the overlay grab only:
//   layerRenderer._pixiContainer         (the layer's 2D display object)
//   renderer.properties.get(tex).__webglTexture  (zero-copy texture bind)
// The core effect no longer depends on either.
// =====================================================================

if (!gdjs._crtLottes3D) {
  // -------------------------------------------------------------------
  // Vertex shader: draws a single full-screen triangle/quad. The quad's
  // PlaneGeometry(2,2) already spans clip space (-1..1), so we bypass any
  // camera/projection and just pass the position straight through.
  // -------------------------------------------------------------------
  const vertexShader = `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = vec4(position.xy, 0.0, 1.0);
    }
  `;

  // -------------------------------------------------------------------
  // Fragment shader: the whole CRT look. Each block is gated by a uniform
  // so any feature can be dialed to zero with no cost to the result (the
  // GPU still runs the math, but the toolkit stays flexible). The final
  // color is mixed against the untouched source by `intensity` so the
  // entire effect has a single master strength / fade knob.
  // -------------------------------------------------------------------
  const fragmentShader = `
    precision highp float;
    varying vec2 vUv;

    uniform sampler2D tDiffuse;   // the rendered 3D scene
    uniform vec2 dimensions;      // real output size in pixels
    uniform vec2 res;             // emulated CRT resolution (the low-res grid)
    uniform float time;           // seconds since effect start (for roll/flicker)

    // Scanline / pixel shape
    uniform float hardScan;       // scanline gap hardness (-16 hard .. -4 soft)
    uniform float hardPix;        // in-line pixel hardness (-6 hard .. -2 soft)

    // Curvature + framing
    uniform float warpX;          // horizontal curvature (bulge derived)
    uniform float warpY;          // vertical curvature
    // Per-side bezel insets (fraction of screen, 0..0.45). Each side is the
    // master Border plus that side's own offset, already combined in JS.
    uniform float borderL;        // left inset
    uniform float borderR;        // right inset
    uniform float borderT;        // top inset
    uniform float borderB;        // bottom inset
    // Independent X/Y stretch of the rendered image (1 = unchanged).
    uniform float stretchX;
    uniform float stretchY;

    // Shadow mask
    uniform float maskDark;       // brightness of "off" mask subpixels (0..1)
    uniform float maskLight;      // brightness multiplier of "lit" subpixels (>=1)

    // Tone
    uniform float brightness;     // flat post-multiply to offset mask/scan dimming
    uniform float bloom;          // bloom intensity multiplier
    uniform float bloomThreshold;  // luminance cutoff point (0..2)
    uniform float bloomKnee;       // soft-knee transition curve (0..1)
    uniform float bloomRadius;     // blur spread radius (1..50)
    uniform vec3 bloomTint;        // RGB color tint for the bloom glow

    // Glitch / motion
    uniform float aberration;     // chromatic aberration in emulated pixels (0..~3)
    uniform float rollSpeed;      // vertical roll bar speed (0 = off)
    uniform float rollHeight;     // roll bar thickness (0..1 of screen)
    uniform float flicker;        // per-frame brightness flicker amount (0..~0.2)
    uniform float interlace;      // 0 = off, 1 = full interlacing dimming of alt lines

    // Color grading
    uniform float saturation;     // 1 = unchanged, 0 = grayscale, >1 = boosted
    uniform float contrast;       // 1 = unchanged
    uniform float gammaCorrect;   // 1 = unchanged; >1 darkens mids, <1 lifts them
    uniform vec3  tint;           // phosphor tint multiplier (1,1,1 = none)

    uniform float intensity;      // master mix 0 = original image .. 1 = full CRT

    // ---- per-group enable flags (1 = on, 0 = off) ---------------------
    // When a group is off, its block is skipped and contributes nothing,
    // regardless of the group's own setting values.
    uniform float enScanlines;
    uniform float enBulge;
    uniform float enBorder;
    uniform float enMask;
    uniform float enBrightness;
    uniform float enBloom;
    uniform float enAberration;
    uniform float enRoll;
    uniform float enFlicker;
    uniform float enInterlace;
    uniform float enColor;
    uniform float enGrain;
    uniform float enBlur;
    uniform float enPixelate;

    // Softness prepass -- the camera's own optics. Applied to the filmed
    // world only, BEFORE the overlay composites, so the HUD stays sharp.
    uniform float blurAmount;     // gaussian radius in real pixels (0..~16)
    uniform float pixelateSize;   // block size in real pixels (1..64)

    // Overlay: the called 2D layer, composited between camera + display.
    uniform float enOverlay;      // 1 = composite the overlay layer
    uniform sampler2D tOverlay;   // grabbed 2D layer (tagged sRGB, like tDiffuse)
    uniform float overlayOpacity; // 0..1 fade for the overlay only
    uniform float overlayGlow;     // phosphor bloom on the overlay (0 = none)

    // Grain (animated pseudo-random noise, pure math, no textures).
    uniform float grainAmount;    // 0..1 strength
    uniform float grainSize;      // cell size in real pixels (1 fine .. coarse)
    uniform float grainColor;     // 0 = mono film grain, 1 = full RGB static
    uniform float grainSpeed;     // 0 = frozen, 1 = fast animation

    // ---- color space helpers -----------------------------------------
    // The render target is tagged sRGB (see JS), so sampling already gives
    // linear-ish values for the GPU; we encode back to sRGB at the very end.
    float ToSrgb1(float c){ return (c<0.0031308)?c*12.92:1.055*pow(c,0.41666)-0.055; }
    vec3 ToSrgb(vec3 c){ return vec3(ToSrgb1(c.r),ToSrgb1(c.g),ToSrgb1(c.b)); }
    // Overlay sampled premultiplied (rgb*a) -- used to bloom the UI's own light.
    vec3 OverlayPM(vec2 uv){ vec4 s = texture2D(tOverlay, uv); return s.rgb * s.a; }

    // Sample the scene at an emulated-grid position, zeroing off-screen
    // reads (this is what darkens the curved edges into a vignette/border).
    vec3 Fetch(vec2 pos, vec2 off){
      pos = floor(pos*res+off)/res;
      if (max(abs(pos.x-0.5), abs(pos.y-0.5)) > 0.5) return vec3(0.0);
      return texture2D(tDiffuse, pos.xy).rgb;
    }

    vec2 Dist(vec2 pos){ pos = pos*res; return -((pos-floor(pos))-vec2(0.5)); }
    float Gaus(float pos, float scale){ return exp2(scale*pos*pos); }

    // 3-tap and 5-tap horizontal gaussian reconstruction of the scanline.
    vec3 Horz3(vec2 pos, float off){
      vec3 b = Fetch(pos, vec2(-1.0, off));
      vec3 c = Fetch(pos, vec2( 0.0, off));
      vec3 d = Fetch(pos, vec2( 1.0, off));
      float dst = Dist(pos).x;
      float wb = Gaus(dst-1.0, hardPix);
      float wc = Gaus(dst+0.0, hardPix);
      float wd = Gaus(dst+1.0, hardPix);
      return (b*wb+c*wc+d*wd)/(wb+wc+wd);
    }
    vec3 Horz5(vec2 pos, float off){
      vec3 a = Fetch(pos, vec2(-2.0, off));
      vec3 b = Fetch(pos, vec2(-1.0, off));
      vec3 c = Fetch(pos, vec2( 0.0, off));
      vec3 d = Fetch(pos, vec2( 1.0, off));
      vec3 e = Fetch(pos, vec2( 2.0, off));
      float dst = Dist(pos).x;
      float wa = Gaus(dst-2.0, hardPix);
      float wb = Gaus(dst-1.0, hardPix);
      float wc = Gaus(dst+0.0, hardPix);
      float wd = Gaus(dst+1.0, hardPix);
      float we = Gaus(dst+2.0, hardPix);
      return (a*wa+b*wb+c*wc+d*wd+e*we)/(wa+wb+wc+wd+we);
    }

    float Scan(vec2 pos, float off){
      float dst = Dist(pos).y;
      return Gaus(dst+off, hardScan);
    }

    // Combine the three nearest scanlines, weighted by vertical distance.
    vec3 Tri(vec2 pos){
      vec3 a = Horz3(pos, -1.0);
      vec3 b = Horz5(pos,  0.0);
      vec3 c = Horz3(pos,  1.0);
      float wa = Scan(pos, -1.0);
      float wb = Scan(pos,  0.0);
      float wc = Scan(pos,  1.0);
      return a*wa + b*wb + c*wc;
    }

    // ---- Overlay reconstruction: SAME math as the scene, but sampling
    // tOverlay, ALPHA-AWARE (vec4), and with the emulated resolution passed in
    // so the amount can interpolate it. This is what gives the UI the footage's
    // real scanlines + pixel structure instead of a flat block-snap.
    vec4 FetchOv(vec2 pos, vec2 off, vec2 r){
      pos = floor(pos*r+off)/r;
      if (max(abs(pos.x-0.5), abs(pos.y-0.5)) > 0.5) return vec4(0.0);
      return texture2D(tOverlay, pos.xy);
    }
    vec2 DistOv(vec2 pos, vec2 r){ pos = pos*r; return -((pos-floor(pos))-vec2(0.5)); }
    vec4 Horz3Ov(vec2 pos, float off, vec2 r){
      vec4 b = FetchOv(pos, vec2(-1.0, off), r);
      vec4 c = FetchOv(pos, vec2( 0.0, off), r);
      vec4 d = FetchOv(pos, vec2( 1.0, off), r);
      float dst = DistOv(pos, r).x;
      float wb = Gaus(dst-1.0, hardPix);
      float wc = Gaus(dst+0.0, hardPix);
      float wd = Gaus(dst+1.0, hardPix);
      return (b*wb+c*wc+d*wd)/(wb+wc+wd);
    }
    vec4 Horz5Ov(vec2 pos, float off, vec2 r){
      vec4 a = FetchOv(pos, vec2(-2.0, off), r);
      vec4 b = FetchOv(pos, vec2(-1.0, off), r);
      vec4 c = FetchOv(pos, vec2( 0.0, off), r);
      vec4 d = FetchOv(pos, vec2( 1.0, off), r);
      vec4 e = FetchOv(pos, vec2( 2.0, off), r);
      float dst = DistOv(pos, r).x;
      float wa = Gaus(dst-2.0, hardPix);
      float wb = Gaus(dst-1.0, hardPix);
      float wc = Gaus(dst+0.0, hardPix);
      float wd = Gaus(dst+1.0, hardPix);
      float we = Gaus(dst+2.0, hardPix);
      return (a*wa+b*wb+c*wc+d*wd+e*we)/(wa+wb+wc+wd+we);
    }
    float ScanOv(vec2 pos, float off, vec2 r){
      float dst = DistOv(pos, r).y;
      return Gaus(dst+off, hardScan);
    }
    vec4 TriOv(vec2 pos, vec2 r){
      vec4 a = Horz3Ov(pos, -1.0, r);
      vec4 b = Horz5Ov(pos,  0.0, r);
      vec4 c = Horz3Ov(pos,  1.0, r);
      float wa = ScanOv(pos, -1.0, r);
      float wb = ScanOv(pos,  0.0, r);
      float wc = ScanOv(pos,  1.0, r);
      // Scanlines darken the COLOUR (the look) but must NOT cut the overlay's
      // COVERAGE -- otherwise the dark gaps become windows that let a bright 3D
      // background punch through the text. So weight rgb by the scanline profile
      // (un-normalized = dark gaps) but normalize alpha so opaque text stays
      // opaque in the gaps (dark TEXT, not background).
      vec3 rgb = a.rgb*wa + b.rgb*wb + c.rgb*wc;
      float cov = (a.a*wa + b.a*wb + c.a*wc) / max(wa + wb + wc, 1e-4);
      return vec4(rgb, cov);
    }

    // Screen curvature ("bulge"). Returns warped UVs.
    vec2 Warp(vec2 pos){
      pos = pos*2.0 - 1.0;
      pos *= vec2(1.0 + (pos.y*pos.y)*warpX, 1.0 + (pos.x*pos.x)*warpY);
      return pos*0.5 + 0.5;
    }

    // RGB shadow mask (rotated stripe pattern, in real pixels).
    //
    // MOIRE FIX: the original used hard if/else stripe boundaries, which are
    // a razor-sharp full-frequency pattern. When that beats against the
    // emulated-resolution grid it produces the screen-locked "comb" moire
    // seen on flat surfaces. Here each channel's lit/unlit value is computed
    // with a SMOOTH profile whose edge softness tracks the on-screen change
    // rate of the pattern (fwidth), so the stripes anti-alias instead of
    // aliasing. This removes the comb while keeping the shadow-mask look.
    vec3 Mask(vec2 pos){
      pos.x += pos.y*3.0;
      // phase in [0,1) across one R-G-B triad
      float ph = fract(pos.x/6.0);
      // how much the phase changes per pixel -> our anti-alias width
      float aa = fwidth(pos.x/6.0);
      aa = clamp(aa, 0.0008, 0.5);

      // Smooth "is this channel the lit one" weights centered on each third.
      // Each channel ramps up near its band center and down away from it.
      // Vectorized: the same math the old 3-iteration loop did, expressed as
      // vec3 ops. smoothstep() takes scalar edges with a vec3 x, so the
      // per-channel result is identical (no behavior change), one less loop.
      vec3 center = vec3(0.1667, 0.5, 0.8333); // band centers for R,G,B
      vec3 d = abs(ph - center);               // distance from each band center
      d = min(d, 1.0 - d);                     // wrap into [0,0.5]
      // band half-width is 1/6; smoothstep gives a soft lit region per channel.
      vec3 w = 1.0 - smoothstep(0.1667 - aa, 0.1667 + aa, d);
      // Blend between the dark floor and the lit level per channel.
      return mix(vec3(maskDark), vec3(maskLight), w);
    }

    // ReShade-style highlight extraction with quadratic soft knee curve
    vec3 ExtractBloom(vec3 c, float threshold, float knee) {
      float luma = dot(c, vec3(0.2126, 0.7152, 0.0722));
      // Soft knee curve: smooth transition around threshold
      // Knee may never exceed the threshold: if it does the curve reaches
      // below zero luma and EVERY pixel (black included) feeds the bloom.
      float k = min(max(knee, 1e-4), max(threshold, 1e-4));
      float soft = clamp(luma - threshold + k, 0.0, 2.0 * k);
      soft = (soft * soft) / (4.0 * k);
      float weight = max(soft, luma - threshold) / max(luma, 1e-4);
      return c * clamp(weight, 0.0, 1.0);
    }

    // Guarded gaussian resolve for the softness prepass. Off-picture taps
    // take zero weight and the sum is normalised by the weight that actually
    // landed, so the picture edge softens instead of fading to black. The
    // per-channel offsets carry chromatic aberration through the blur, so
    // switching blur on does not silently drop the split.
    vec3 BlurScene(vec2 uv, float radiusPx, vec2 ab) {
      vec2 r = vec2(max(radiusPx, 0.0)) / max(dimensions, vec2(1.0));
      vec3 sum = vec3(0.0);
      float wsum = 0.0;
      for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
          vec2 o = vec2(float(x), float(y));
          vec2 suv = uv + o * r;
          float ins = (max(abs(suv.x - 0.5), abs(suv.y - 0.5)) > 0.5) ? 0.0 : 1.0;
          float w = exp2(-(o.x*o.x + o.y*o.y) * 0.9) * ins;
          vec2 cuv = clamp(suv, vec2(0.0), vec2(1.0));
          sum.r += texture2D(tDiffuse, clamp(cuv + ab, vec2(0.0), vec2(1.0))).r * w;
          sum.g += texture2D(tDiffuse, cuv).g * w;
          sum.b += texture2D(tDiffuse, clamp(cuv - ab, vec2(0.0), vec2(1.0))).b * w;
          wsum += w;
        }
      }
      return (wsum > 1e-4) ? sum / wsum : vec3(0.0);
    }

    // Guarded bloom tap. Sampling tDiffuse directly let taps that fall
    // outside the picture read CLAMP_TO_EDGE texels, smearing the edge
    // colour outward into a bright rectangle against the bezel. Match
    // Fetch(): off-picture reads contribute nothing.
    vec3 BloomTap(vec2 uv) {
      if (max(abs(uv.x - 0.5), abs(uv.y - 0.5)) > 0.5) return vec3(0.0);
      return ExtractBloom(texture2D(tDiffuse, uv).rgb, bloomThreshold, bloomKnee);
    }

    // ReShade / Advanced Bloom multi-tier hierarchical diffusion
    vec3 BloomGlow(vec2 uv) {
      vec3 totalBloom = vec3(0.0);
      float totalWeight = 0.0;

      // Core center sample
      vec3 centerBloom = BloomTap(uv);
      totalBloom += centerBloom * 0.45;
      totalWeight += 0.45;

      // 4 progressive tiers covering tight specular highlights to wide atmospheric diffusion
      float tiers[4];
      tiers[0] = 1.0;
      tiers[1] = 2.5;
      tiers[2] = 6.0;
      tiers[3] = 15.0;

      float weights[4];
      weights[0] = 0.35;
      weights[1] = 0.25;
      weights[2] = 0.20;
      weights[3] = 0.12;

      // Radius is REAL pixels, always. It used to switch to 1.0/res whenever
      // scanlines were on, which measured the spread in EMULATED pixels -- so
      // pixel size / scanline count silently multiplied it (radius 1 at pixel
      // size 6 spread like radius 6), and the widest tier landed 8 lone taps a
      // quarter of a screen apart, which read as blocks rather than glow.
      // Now the same number means the same spread whatever the emulated grid,
      // the camera prepass, or the resolution is doing.
      vec2 baseStep = (1.0 / max(dimensions, vec2(1.0, 1.0))) * bloomRadius;

      for (int t = 0; t < 4; t++) {
        vec2 tierStep = baseStep * tiers[t];
        vec3 tierCol = vec3(0.0);

        tierCol += BloomTap(uv + vec2( tierStep.x, 0.0));
        tierCol += BloomTap(uv + vec2(-tierStep.x, 0.0));
        tierCol += BloomTap(uv + vec2(0.0,  tierStep.y));
        tierCol += BloomTap(uv + vec2(0.0, -tierStep.y));
        tierCol += BloomTap(uv + vec2( tierStep.x,  tierStep.y) * 0.707);
        tierCol += BloomTap(uv + vec2(-tierStep.x,  tierStep.y) * 0.707);
        tierCol += BloomTap(uv + vec2( tierStep.x, -tierStep.y) * 0.707);
        tierCol += BloomTap(uv + vec2(-tierStep.x, -tierStep.y) * 0.707);

        totalBloom += (tierCol / 8.0) * weights[t];
        totalWeight += weights[t];
      }

      return (totalBloom / max(totalWeight, 1e-4)) * bloomTint;
    }

    // Using code from another source this is rewritten.
    float grainHash(vec2 p) {
      vec3 p3 = fract(vec3(p.xyx) * .1031);
      p3 += dot(p3, p3.yzx + 33.33);
      return fract((p3.x + p3.y) * p3.z);
    }

    void main() {
      // 3D-only image (no overlay) for the master-opacity blend at the end.
      vec3 original = texture2D(tDiffuse, vUv).rgb;

      // ============================================================
      // GEOMETRY -- tube shape shared by camera + display (not graded).
      // ============================================================

      // --- Border (enBorder): per-side bezel inset. [unchanged]
      vec2 uv = vUv;
      float borderMask = 1.0;
      if (enBorder > 0.5) {
        vec2 lo = vec2(clamp(borderL, 0.0, 0.45), clamp(borderB, 0.0, 0.45));
        vec2 hi = vec2(1.0 - clamp(borderR, 0.0, 0.45), 1.0 - clamp(borderT, 0.0, 0.45));
        vec2 span = max(hi - lo, vec2(1e-3));
        uv = (vUv - lo) / span;
        vec2 e = max(fwidth(uv), vec2(1e-4));
        vec2 m = smoothstep(vec2(0.0), e, uv) *
                 (vec2(1.0) - smoothstep(vec2(1.0) - e, vec2(1.0), uv));
        borderMask = m.x * m.y;
      }

      // --- Screen bulge (enBulge): curve the inset image. [unchanged]
      vec2 pos = (enBulge > 0.5) ? Warp(uv) : uv;

      // --- Image stretch. [unchanged]
      pos = (pos - 0.5) / max(vec2(stretchX, stretchY), vec2(0.01)) + 0.5;

      // --- Softness prepass: pixelate (enPixelate). [CAMERA-ONLY, pre-overlay]
      //     'spos' is the sample coordinate for the FILMED WORLD only. The
      //     overlay composite and the whole display stage keep using 'pos', so
      //     the HUD never inherits the prepass: a soft camera on a sharp screen.
      //     Independent of pixelSize / scanlineCount, which drive the scanline
      //     grid -- this works with scanlines off and leaves res alone.
      vec2 spos = pos;
      if (enPixelate > 0.5 && pixelateSize > 1.0) {
        vec2 blocks = max(dimensions / max(pixelateSize, 1.0), vec2(1.0));
        spos = (floor(spos * blocks) + 0.5) / blocks;
      }

      // ============================================================
      // CAMERA / SIGNAL STAGE -- the filmed world ONLY. The overlay HUD
      // must NOT receive any of this (it was never in front of the lens
      // / on the tape grade).
      //   CAMERA-ONLY: aberration, scanline reconstruction, bloom, colour.
      // ============================================================

      // --- Scanlines (enScanlines) + Aberration (enAberration). [CAMERA-ONLY]
      vec3 col;
      bool doScan = enScanlines > 0.5;
      // Everything here samples 'spos' (the prepass coordinate), never 'pos'.
      vec2 abOfs = vec2(0.0);
      if (enAberration > 0.5 && aberration > 0.0) {
        vec2 dir = (spos - 0.5);
        abOfs = dir * (aberration / res);
        if (doScan) {
          col.r = Tri(spos + abOfs).r;
          col.g = Tri(spos).g;
          col.b = Tri(spos - abOfs).b;
        } else {
          col.r = Fetch(spos + abOfs, vec2(0.0)).r;
          col.g = Fetch(spos, vec2(0.0)).g;
          col.b = Fetch(spos - abOfs, vec2(0.0)).b;
        }
      } else {
        col = doScan ? Tri(spos) : Fetch(spos, vec2(0.0));
      }

      // --- Softness prepass: blur (enBlur). [CAMERA-ONLY, pre-overlay]
      //     A defocused lens. Radius 0 collapses every tap onto one texel, so
      //     small values stay near the sharp image and scanline detail softens
      //     gradually as the radius grows.
      if (enBlur > 0.5 && blurAmount > 0.0) {
        col = BlurScene(spos, blurAmount, abOfs);
      }

      // --- Brightness (enBrightness). [STAYS camera-side: it drives bloom.]
      //     NOTE: mask moved to the display stage below, so brightness no
      //     longer pre-lifts a masked image, and the HUD is mask-dimmed with
      //     no lift. If the HUD reads dark, pre-brighten the HUD layer or add
      //     a small lift just before the mask block. Moving brightness whole
      //     would break the bloom coupling (a 3D-look change), so it stays.
      if (enBrightness > 0.5) {
        col *= brightness;
      }

      // --- Bloom (enBloom). [CAMERA-ONLY: lens/optics glow on the world.]
      if (enBloom > 0.5 && bloom > 0.0) {
        vec3 glow = BloomGlow(spos);
        if (enBrightness > 0.5) glow *= brightness;
        // Clip the glow to the picture -- the same test grain and the overlay
        // use. Guarding the TAPS stops edge texels smearing outward, but a
        // fragment sitting just outside the warped edge still has taps landing
        // inside, so without this the glow bleeds into the bulge margin and
        // spills over the bezel.
        float bInside = (max(abs(pos.x - 0.5), abs(pos.y - 0.5)) > 0.5) ? 0.0 : 1.0;
        col += glow * (bloom * 1.5) * bInside;
      }

      // --- Colour grading (enColor). [CAMERA-ONLY: the footage grade.]
      //     (tint is the one sub-component arguably a tube/phosphor property
      //      -- split it out here if you ever want it on the HUD.)
      if (enColor > 0.5) {
        float luma = dot(col, vec3(0.299, 0.587, 0.114));
        col = mix(vec3(luma), col, saturation);
        col = (col - 0.5) * contrast + 0.5;
        col = pow(max(col, 0.0), vec3(gammaCorrect));
        col *= tint;
      }

      // ============================================================
      // COMPOSITE -- lay the called 2D layer in between camera + display.
      // Sampled at the warped 'pos' so the HUD follows curvature + stretch,
      // but NOT Tri()-reconstructed (no re-pixelating) and NOT aberration-
      // split. tOverlay is tagged sRGB like tDiffuse, so it samples in the
      // SAME space as the scene -- composite directly, no manual decode; the
      // ToSrgb() at the end encodes the combined result once. Killed outside
      // the picture exactly like Fetch() does for the scene.
      // ============================================================
      if (enOverlay > 0.5) {
        float inside = (max(abs(pos.x - 0.5), abs(pos.y - 0.5)) > 0.5) ? 0.0 : 1.0;
        // PIXI RenderTexture -> Three is V-flipped (vertical only), so mirror V.
        vec2 ovUv = vec2(pos.x, 1.0 - pos.y);
        // Overlay is always reconstructed at the footage resolution (match is
        // fixed at full). Mirror the scene: scanlines ON -> TriOv; scanlines OFF
        // -> FetchOv (pixel-snap only, no gaps), so turning scanlines off stops
        // affecting the UI exactly like the 3D.
        vec4 ov = (enScanlines > 0.5) ? TriOv(ovUv, res) : FetchOv(ovUv, vec2(0.0), res);
        // If the grab ever yields PREMULTIPLIED alpha, swap the mix for:
        //   float a = clamp(ov.a*overlayOpacity,0.0,1.0)*inside;
        //   col = col*(1.0-a) + ov.rgb*overlayOpacity*inside;
        col = mix(col, ov.rgb, clamp(ov.a * overlayOpacity, 0.0, 1.0) * inside);

        // Phosphor glow: bloom the overlay's OWN bright pixels so the UI reads
        // as light emitted by a tube, not a flat decal. A small soft ring of
        // premultiplied samples, added on top. Sharp source stays sharp; only
        // the glow is soft. Gated so it costs nothing at 0.
        if (overlayGlow > 0.0) {
          vec2 r1 = 1.5 / dimensions;
          vec2 r2 = 3.5 / dimensions;
          vec3 g = OverlayPM(ovUv) * 0.5;
          g += OverlayPM(ovUv + vec2( r1.x, 0.0));
          g += OverlayPM(ovUv + vec2(-r1.x, 0.0));
          g += OverlayPM(ovUv + vec2(0.0,  r1.y));
          g += OverlayPM(ovUv + vec2(0.0, -r1.y));
          g += OverlayPM(ovUv + vec2( r2.x,  r2.y)) * 0.5;
          g += OverlayPM(ovUv + vec2(-r2.x,  r2.y)) * 0.5;
          g += OverlayPM(ovUv + vec2( r2.x, -r2.y)) * 0.5;
          g += OverlayPM(ovUv + vec2(-r2.x, -r2.y)) * 0.5;
          g /= 6.5;
          col += g * overlayGlow * inside;
        }
      }

      // ============================================================
      // DISPLAY STAGE -- the tube/tape the COMBINED image plays through.
      // Everything here reaches the HUD too. The first four MOVED up from
      // the camera side; each now runs after colour (e.g. mask multiplies
      // the graded composite, not the pre-grade signal). Intentional shift.
      // ============================================================

      // --- Shadow mask (enMask). [MOVED to display: phosphor triad over all.]
      if (enMask > 0.5) {
        col *= Mask(vUv * dimensions);
      }

      // --- Interlacing (enInterlace). [MOVED to display.]
      if (enInterlace > 0.5 && interlace > 0.0) {
        float lineParity = mod(floor(pos.y * res.y) + floor(time*60.0), 2.0);
        col *= mix(1.0, 1.0 - 0.5*interlace, lineParity);
      }

      // --- Rolling bar (enRoll). [MOVED to display.]
      if (enRoll > 0.5 && rollSpeed != 0.0 && rollHeight > 0.0) {
        float barPos = fract(pos.y - time*rollSpeed);
        float bar = smoothstep(0.0, rollHeight, barPos) *
                    (1.0 - smoothstep(rollHeight, rollHeight*2.0, barPos));
        col *= 1.0 - 0.4*bar;
      }

      // --- Flicker (enFlicker). [MOVED to display.]
      if (enFlicker > 0.5 && flicker > 0.0) {
        float f = 1.0 - flicker * fract(sin(time*123.4)*43758.5453);
        col *= f;
      }

      // --- Grain (enGrain). [already display-side: the tape medium.]
      if (enGrain > 0.5 && grainAmount > 0.0) {
        float cs = max(grainSize, 1.0);
        // Key the grain cell off the WARPED coordinate (pos), not flat vUv, so
        // the grain rides the tube curvature/stretch with the picture instead of
        // staying on a flat rectangular grid when screen bulge is up.
        vec2 cell = floor((pos * dimensions) / cs);
        float t = floor(time * grainSpeed * 50.0);
        vec3 n = vec3(
          grainHash(cell + vec2(t, t * 7.13)),
          grainHash(cell + vec2(t * 3.71, t * 11.29)),
          grainHash(cell + vec2(t * 5.83, t * 17.91))
        ) - 0.5;
        vec3 noise = mix(vec3(n.r), n, clamp(grainColor, 0.0, 1.0));
        float gluma = dot(col, vec3(0.299, 0.587, 0.114));
        float response = mix(1.0, 1.0 - sqrt(clamp(gluma, 0.0, 1.0)), 0.5);
        // Clip grain to the warped picture region (same off-screen test the
        // scene sampling uses), so grain rides the bulge and stops at the curved
        // edge instead of sitting flat on the black margins the bulge creates.
        float gInside = (max(abs(pos.x - 0.5), abs(pos.y - 0.5)) > 0.5) ? 0.0 : 1.0;
        col += noise * grainAmount * response * gInside;
      }

      // --- Border kill: blacks out the bezel for the combined image. [display]
      col *= borderMask;

      // ============================================================
      // OUTPUT
      // ============================================================
      // Linear out: the composer's OutputPass does the sRGB encode. Encoding
      // here as well is the double-encode the pre-0.8.0 build shipped with.
      vec3 outRgb = max(col, 0.0);
      // master-mix blends against the 3D-only 'original', so as intensity
      // drops the HUD fades out with the effect (power-on fade keeps HUD +
      // CRT together). To keep the HUD at intensity 0, composite it back in
      // on this line instead of relying on 'col'.
      // Mask the untouched image by the same bezel, faded in with the master
      // mix, so a partial opacity can no longer show the raw picture inside
      // the border. intensity 0 still yields the original frame untouched.
      float mixAmt = clamp(intensity, 0.0, 1.0);
      vec3 baseRgb = mix(original, original * borderMask, mixAmt);
      gl_FragColor = vec4(mix(baseRgb, outRgb, mixAmt), 1.0);
    }
  `;

  // ===================================================================
  // SHARED SETTINGS
  // Both the behavior and the actions write here. Read fresh every frame
  // by the processor, so any change (editor seed, runtime action, preset,
  // fade) takes effect immediately. Units/ranges noted per field.
  // ===================================================================
  const DEFAULTS = {
    enabled: true,
    // Master strength of the whole effect. 0 = original image, 1 = full CRT.
    intensity: 1.0,

    // Scanline + pixel shape
    scanlineHardness: -8.0,   // -16 hard .. -4 soft
    pixelHardness: -3.0,      // -6 hard .. -2 soft

    // Resolution of the emulated grid. scanlineCount (absolute virtual
    // vertical resolution) takes priority when > 0; otherwise pixelSize
    // (realResolution / pixelSize) is used.
    scanlineCount: 240,       // 0 to use pixelSize instead
    pixelSize: 6.0,           // only used when scanlineCount == 0

    // Softness prepass (camera optics, applied before the overlay).
    blurAmount: 0.0,          // gaussian radius in real pixels (0..16)
    pixelateSize: 4.0,        // block size in real pixels (1..64)

    // Curvature + framing
    screenBulge: 1.0,         // 0 flat, 1 = original Lottes curve, 2 = strong
    border: 0.0,              // master black bezel inset, 0..0.45 of the screen
    // Per-side EXTRA inset added on top of the master border (0..0.45 each).
    // All 0 => uniform bezel from `border` alone. Lets one side be deeper.
    borderLeft: 0.0,
    borderRight: 0.0,
    borderTop: 0.0,
    borderBottom: 0.0,
    // Independent X/Y image stretch (1 = unchanged, >1 stretch, <1 squash).
    stretchX: 1.0,
    stretchY: 1.0,

    // Shadow mask
    shadowMaskDarkLevel: 0.5, // 0..1
    shadowMaskLightLevel: 1.5,// >= 1

    // Tone
    brightness: 1.2,          // 1 = none
    bloom: 0.0,               // 0..~5 (intensity scale)
    bloomThreshold: 0.25,      // 0..2 (brightness cutoff)
    bloomRadius: 5.0,         // 1..50 (blur radius spread)
    bloomKnee: 0.5,           // 0..1 (soft-knee transition curve, default 0.5)
    bloomTintR: 1.0, bloomTintG: 1.0, bloomTintB: 1.0, // bloom tint multipliers

    // Glitch / motion
    aberration: 0.0,          // 0..~3 emulated pixels
    rollSpeed: 0.0,           // 0 = off
    rollHeight: 0.1,          // 0..1
    flicker: 0.0,             // 0..~0.2
    interlace: 0.0,           // 0 off .. 1 full

    // Color grading
    saturation: 1.0,          // 0 grayscale, 1 normal, >1 boosted
    contrast: 1.0,            // 1 = none
    gamma: 1.0,               // 1 = none
    tintR: 1.0, tintG: 1.0, tintB: 1.0, // phosphor tint (1,1,1 = none)

    // Grain (animated noise). Amount 0 = none; size/color/speed shape the look
    // (fine static .. coarse VHS, mono film grain .. colour static, frozen ..
    // fast). Speed defaults to animated so raising amount gives moving grain.
    grainAmount: 0.0,         // 0..1
    grainSize: 1.0,           // >= 1 real pixels per cell
    grainColor: 0.0,          // 0 mono .. 1 colour
    grainSpeed: 1.0,          // 0 frozen .. 1 fast

    // --- Per-group enable flags. ALL DEFAULT OFF: a freshly-added effect
    //     does nothing until a group is switched on. Each gates its block
    //     in the shader regardless of that group's setting values.
    enScanlines: false,
    enBulge: false,
    enBorder: false,
    enMask: false,
    enBrightness: false,
    enBloom: false,
    enAberration: false,
    enRoll: false,
    enFlicker: false,
    enInterlace: false,
    enColor: false,
    enGrain: false,
    enBlur: false,
    enPixelate: false,

    // Overlay layer compositing. OFF until an action names a layer.
    enOverlay: false,
    overlayOpacity: 1.0,   // 0..1, fades only the overlay
    overlayGlow: 0.0,      // phosphor bloom on the overlay: bright UI glows like it's on a tube (0 = off; ~0.3-0.8 typical)
    overlayLayerName: '',  // which 2D layer to pull in ('' = none)

    // Which 3D layer's composer the pass is inserted into. '' = the base
    // layer, which is where GDevelop puts 3D by default.
    targetLayerName: '',
  };

  // The single live settings object the whole extension shares.
  const settings = Object.assign({}, DEFAULTS);

  // ===================================================================
  // THE PASS
  // 3DCRT+ runs as a real post-processing pass inside the target layer's
  // EffectComposer -- the same chain, and the same public entry point
  // (layerRenderer.addPostProcessingPass), that GDevelop's own 3D effects
  // use (Scene3D::BrightnessAndContrast, Bloom, Exposure, HueAndSaturation).
  //
  // This replaces the old approach of overriding THREE.WebGLRenderer.render.
  // That override sat on the SHARED renderer, so it was in the path of every
  // 3D layer and every scene, which is why it collided with GDevelop's own
  // layer effects and why two 3D layers overwrote each other. A pass touches
  // one layer's composer and nothing else.
  //
  // Colour space: the composer works in LINEAR and its final OutputPass does
  // the sRGB encode. So this pass reads linear and must write linear -- the
  // shader's old trailing ToSrgb() is gone. (The previous build encoded
  // twice: once writing into an sRGB-tagged target, once in the shader.)
  // ===================================================================
  const CRT_UNIFORMS = () => ({
    tDiffuse: { value: null },
    dimensions: { value: new THREE.Vector2() },
    res: { value: new THREE.Vector2() },
    time: { value: 0 },
    hardScan: { value: 0 }, hardPix: { value: 0 },
    warpX: { value: 0 }, warpY: { value: 0 },
    borderL: { value: 0 }, borderR: { value: 0 },
    borderT: { value: 0 }, borderB: { value: 0 },
    stretchX: { value: 1 }, stretchY: { value: 1 },
    maskDark: { value: 0 }, maskLight: { value: 0 },
    brightness: { value: 1 }, bloom: { value: 0 },
    bloomThreshold: { value: 0.25 }, bloomRadius: { value: 5.0 },
    bloomKnee: { value: 0.5 }, bloomTint: { value: new THREE.Vector3(1, 1, 1) },
    aberration: { value: 0 }, rollSpeed: { value: 0 },
    rollHeight: { value: 0.1 }, flicker: { value: 0 },
    interlace: { value: 0 }, saturation: { value: 1 },
    contrast: { value: 1 }, gammaCorrect: { value: 1 },
    tint: { value: new THREE.Vector3(1, 1, 1) },
    intensity: { value: 1 },
    enScanlines: { value: 0 }, enBulge: { value: 0 },
    enBorder: { value: 0 }, enMask: { value: 0 },
    enBrightness: { value: 0 }, enBloom: { value: 0 },
    enAberration: { value: 0 }, enRoll: { value: 0 },
    enFlicker: { value: 0 }, enInterlace: { value: 0 },
    enColor: { value: 0 }, enGrain: { value: 0 },
    enBlur: { value: 0 }, enPixelate: { value: 0 },
    blurAmount: { value: 0 }, pixelateSize: { value: 4 },
    grainAmount: { value: 0 }, grainSize: { value: 1 },
    grainColor: { value: 0 }, grainSpeed: { value: 1 },
    enOverlay: { value: 0 }, tOverlay: { value: null },
    overlayOpacity: { value: 1 },
    overlayGlow: { value: 0 },
  });

  // Built lazily: THREE_ADDONS.ShaderPass must exist before we can subclass it.
  let CRTLottesPass = null;

  const buildPassClass = () => {
    if (CRTLottesPass) return CRTLottesPass;
    if (typeof THREE_ADDONS === 'undefined' || !THREE_ADDONS.ShaderPass) return null;

    CRTLottesPass = class extends THREE_ADDONS.ShaderPass {
      constructor() {
        super({
          uniforms: CRT_UNIFORMS(),
          vertexShader: vertexShader,
          fragmentShader: fragmentShader,
        });
        // fwidth() in Mask() and the border edge needs the derivatives
        // extension on WebGL1. Harmless on WebGL2. ShaderPass builds the
        // material itself, so this is set after construction.
        this.material.extensions = { derivatives: true };
        this.material.depthTest = false;
        this.material.depthWrite = false;

        this._startTime = (typeof performance !== 'undefined'
          ? performance.now() : Date.now());
        this._runtimeScene = null;
        this._overlayTexture = null;
        this._pixiRT = null;
        this._pixiRTOwned = false;
        this._erroredOnce = false;
      }

      // The composer drives this. readBuffer holds the layer's rendered 3D
      // (RenderPass already ran), writeBuffer is where we hand it onward.
      render(renderer, writeBuffer, readBuffer, deltaTime, maskActive) {
        try {
          const size = renderer.getDrawingBufferSize(new THREE.Vector2());
          const w = Math.max(1, Math.round(size.x));
          const h = Math.max(1, Math.round(size.y));

          // Overlay grab. Only when an action switched it on AND named a
          // layer, so the default path costs nothing.
          if (settings.enOverlay && settings.overlayLayerName && this._runtimeScene) {
            this._ensureOverlay(renderer, this._runtimeScene, settings.overlayLayerName, w, h);
          }

          // Re-assert the backdrop every frame. See applySceneBackground:
          // without it a 2D layer rendering first leaves this layer with
          // background === null and the sky reads as opaque black.
          if (this._runtimeScene && this._layerRenderer) {
            applySceneBackground(this, this._runtimeScene, this._layerRenderer);
          }

          this._updateUniforms(w, h);
        } catch (e) {
          if (!this._erroredOnce) {
            console.error('CRT3D: uniform update failed, drawing pass anyway.', e);
            this._erroredOnce = true;
          }
        }
        super.render(renderer, writeBuffer, readBuffer, deltaTime, maskActive);
      }

      _updateUniforms(w, h) {
        const u = this.uniforms;
        const now = (typeof performance !== 'undefined' ? performance.now() : Date.now());
        u.time.value = (now - this._startTime) / 1000;
        u.dimensions.value.set(w, h);

        // Emulated resolution: absolute scanline count wins; else divisor.
        if (settings.scanlineCount > 0) {
          const resY = Math.max(2, Math.round(settings.scanlineCount));
          const resX = Math.max(2, Math.round(resY * (w / h)));
          u.res.value.set(resX, resY);
        } else {
          const divisor = Math.max(settings.pixelSize, 1);
          u.res.value.set(w / divisor, h / divisor);
        }

        u.hardScan.value = settings.scanlineHardness;
        u.hardPix.value = settings.pixelHardness;

        const bulge = Math.max(settings.screenBulge, 0);
        u.warpX.value = bulge / 32;
        u.warpY.value = bulge / 24;

        // Effective per-side inset = master border + that side's offset.
        var bm = settings.border;
        u.borderL.value = Math.min(Math.max(bm + settings.borderLeft, 0), 0.45);
        u.borderR.value = Math.min(Math.max(bm + settings.borderRight, 0), 0.45);
        u.borderT.value = Math.min(Math.max(bm + settings.borderTop, 0), 0.45);
        u.borderB.value = Math.min(Math.max(bm + settings.borderBottom, 0), 0.45);
        u.stretchX.value = settings.stretchX;
        u.stretchY.value = settings.stretchY;
        u.maskDark.value = settings.shadowMaskDarkLevel;
        u.maskLight.value = settings.shadowMaskLightLevel;
        u.brightness.value = settings.brightness;
        u.bloom.value = settings.bloom;
        u.bloomThreshold.value = settings.bloomThreshold;
        u.bloomRadius.value = settings.bloomRadius;
        u.bloomKnee.value = settings.bloomKnee;
        u.bloomTint.value.set(settings.bloomTintR, settings.bloomTintG, settings.bloomTintB);
        u.aberration.value = settings.aberration;
        u.rollSpeed.value = settings.rollSpeed;
        u.rollHeight.value = settings.rollHeight;
        u.flicker.value = settings.flicker;
        u.interlace.value = settings.interlace;
        u.saturation.value = settings.saturation;
        u.contrast.value = settings.contrast;
        u.gammaCorrect.value = settings.gamma;
        u.tint.value.set(settings.tintR, settings.tintG, settings.tintB);
        u.grainAmount.value = settings.grainAmount;
        u.grainSize.value = settings.grainSize;
        u.grainColor.value = settings.grainColor;
        u.grainSpeed.value = settings.grainSpeed;
        u.intensity.value = settings.intensity;

        u.enScanlines.value = settings.enScanlines ? 1 : 0;
        u.enBulge.value = settings.enBulge ? 1 : 0;
        u.enBorder.value = settings.enBorder ? 1 : 0;
        u.enMask.value = settings.enMask ? 1 : 0;
        u.enBrightness.value = settings.enBrightness ? 1 : 0;
        u.enBloom.value = settings.enBloom ? 1 : 0;
        u.enAberration.value = settings.enAberration ? 1 : 0;
        u.enRoll.value = settings.enRoll ? 1 : 0;
        u.enFlicker.value = settings.enFlicker ? 1 : 0;
        u.enInterlace.value = settings.enInterlace ? 1 : 0;
        u.enColor.value = settings.enColor ? 1 : 0;
        u.enGrain.value = settings.enGrain ? 1 : 0;
        u.enBlur.value = settings.enBlur ? 1 : 0;
        u.enPixelate.value = settings.enPixelate ? 1 : 0;
        u.blurAmount.value = settings.blurAmount;
        u.pixelateSize.value = settings.pixelateSize;
        u.tOverlay.value = this._overlayTexture || null;
        u.enOverlay.value = (settings.enOverlay && this._overlayTexture) ? 1 : 0;
        u.overlayOpacity.value = settings.overlayOpacity;
        u.overlayGlow.value = settings.overlayGlow;
      }

      _ensureOverlay(three, runtimeScene, layerName, w, h) {
        // Capture the named 2D layer's PIXI container into a RenderTexture and
        // bind its GL handle into a Three texture (zero-copy; shared context).
        // Any failure leaves _overlayTexture null so the composite self-disables.
        try {
          const gr = runtimeScene.getGame().getRenderer();
          const pixi = gr.getPIXIRenderer && gr.getPIXIRenderer();
          if (!pixi || !three || typeof PIXI === 'undefined') { this._overlayTexture = null; return; }

          const layer = runtimeScene.getLayer(layerName);
          const lr = layer && layer.getRenderer && layer.getRenderer();
          const container = lr && lr._pixiContainer;   // the layer's 2D objects
          if (!container) { this._overlayTexture = null; return; }

          if (!this._pixiRT) {
            this._pixiRT = PIXI.RenderTexture.create({ width: w, height: h });
          } else if (this._pixiRT.width !== w || this._pixiRT.height !== h) {
            this._pixiRT.resize(w, h);
          }
          this._pixiRTOwned = true;

          // Re-sync PIXI's GL state BEFORE rendering (Three left the shared
          // context in its own state, so PIXI would otherwise capture nothing).
          try { if (pixi.reset) pixi.reset(); } catch (e) {}

          const pv = container.visible, pr = container.renderable, pa = container.alpha;
          container.visible = true; container.renderable = true; container.alpha = 1;
          pixi.render(container, { renderTexture: this._pixiRT, clear: true });
          container.visible = pv; container.renderable = pr; container.alpha = pa;

          // Rebind PIXI to the SCREEN framebuffer, or every other 2D layer
          // GDevelop draws later this frame inherits the RenderTexture's
          // flipped projection and comes out mirrored.
          try { if (pixi.renderTexture && pixi.renderTexture.bind) pixi.renderTexture.bind(null); } catch (e) {}
          try { if (pixi.reset) pixi.reset(); } catch (e) {}

          // Hand the context back to Three. super.render() re-binds the
          // composer's target straight after, so losing it here is safe.
          try { if (three.resetState) three.resetState(); } catch (e) {}

          const base = this._pixiRT.baseTexture;
          if (pixi.texture && pixi.texture.bind) pixi.texture.bind(base, 0);
          const glRec = base._glTextures && base._glTextures[pixi.CONTEXT_UID];
          const glHandle = glRec && glRec.texture;
          if (!glHandle) { this._overlayTexture = null; return; }

          if (!this._overlayTexture) {
            const t = new THREE.Texture();
            t.isRenderTargetTexture = true;
            t.minFilter = THREE.LinearFilter; t.magFilter = THREE.LinearFilter;
            t.generateMipmaps = false;
            if (THREE.SRGBColorSpace !== undefined) t.colorSpace = THREE.SRGBColorSpace;
            else if (THREE.sRGBEncoding !== undefined) t.encoding = THREE.sRGBEncoding;
            this._overlayTexture = t;
          }
          this._overlayOwner = three;
          const props = three.properties && three.properties.get(this._overlayTexture);
          if (props) { props.__webglTexture = glHandle; props.__webglInit = true; }
          else { this._overlayTexture = null; }
        } catch (e) {
          this._overlayTexture = null;
        }
      }

      dispose() {
        try { if (super.dispose) super.dispose(); } catch (e) {}
        try { this.material.dispose(); } catch (e) {}
        try {
          // Clear the borrowed GL handle so Three doesn't delete PIXI's
          // texture, then dispose our wrapper.
          if (this._overlayTexture && this._overlayOwner) {
            const p = this._overlayOwner.properties &&
                      this._overlayOwner.properties.get(this._overlayTexture);
            if (p) { p.__webglTexture = undefined; p.__webglInit = false; }
          }
          if (this._overlayTexture) {
            try { this._overlayTexture.dispose(); } catch (e) {}
            this._overlayTexture = null;
          }
        } catch (e) {}
        try { if (this._pixiRT && this._pixiRTOwned) { this._pixiRT.destroy(true); } this._pixiRT = null; } catch (e) {}
      }
    };
    return CRTLottesPass;
  };

  // ===================================================================
  // ATTACHMENT
  // One pass instance, attached to exactly one layer's composer at a time.
  // Re-attached when the target layer changes or when a scene rebuilds its
  // layer renderers (the composer is recreated, so the old pass is gone).
  // ===================================================================
  const state = {
    pass: null,
    attachedRenderer: null,   // the LayerPixiRenderer we inserted into
    attachedLayerName: null,
  };

  const getLayerRenderer = (runtimeScene, layerName) => {
    try {
      const name = layerName || '';
      if (runtimeScene.hasLayer && !runtimeScene.hasLayer(name)) return null;
      const layer = runtimeScene.getLayer(name);
      const lr = layer && layer.getRenderer && layer.getRenderer();
      // Only 3D layers own a composer; a pure 2D layer has none.
      if (!lr || typeof lr.addPostProcessingPass !== 'function') return null;
      if (typeof lr.getThreeEffectComposer === 'function' && !lr.getThreeEffectComposer()) return null;
      return lr;
    } catch (e) { return null; }
  };

  // GDevelop assigns threeScene.background only on the FIRST layer it
  // renders, and for every later 3D layer it runs:
  //     a.background === this._backgroundColor && (a.background = null)
  // -- an IDENTITY check against the Color instance GDevelop itself created.
  // So assigning OUR OWN Color sticks: GDevelop never nulls it, whatever the
  // layer order. RenderPass then paints the backdrop into the composer
  // buffer, so the sky is captured and takes the CRT treatment instead of
  // reading as opaque black over a white background.
  //
  // This runs from the pass's own render(), so it does not need a behavior
  // object on the scene -- driving the effect purely from actions works too.
  const applySceneBackground = (pass, runtimeScene, layerRenderer) => {
    try {
      if (!pass || !layerRenderer || typeof layerRenderer.getThreeScene !== 'function') return;
      const sc = layerRenderer.getThreeScene();
      if (!sc || typeof runtimeScene.getBackgroundColor !== 'function') return;
      if (!pass._bgColor) pass._bgColor = new THREE.Color();
      pass._bgColor.set(runtimeScene.getBackgroundColor());
      if (sc.background !== pass._bgColor) sc.background = pass._bgColor;
    } catch (e) {}
  };

  // Hand the backdrop back when the effect is removed, so stopping the
  // effect does not leave our Color pinned on the layer.
  const releaseSceneBackground = () => {
    try {
      const lr = state.attachedRenderer;
      if (!lr || !state.pass || !state.pass._bgColor) return;
      const sc = lr.getThreeScene && lr.getThreeScene();
      if (sc && sc.background === state.pass._bgColor) sc.background = null;
    } catch (e) {}
  };

  const detach = () => {
    releaseSceneBackground();
    if (state.pass && state.attachedRenderer) {
      try { state.attachedRenderer.removePostProcessingPass(state.pass); } catch (e) {}
    }
    state.attachedRenderer = null;
    state.attachedLayerName = null;
  };

  // Make sure the pass exists and is inserted into the right layer's chain.
  // Returns true once the pass is live.
  const attach = (runtimeScene, layerName) => {
    if (typeof THREE === 'undefined') return false;
    const Cls = buildPassClass();
    if (!Cls) return false;                       // THREE_ADDONS not ready yet

    const lr = getLayerRenderer(runtimeScene, layerName);
    if (!lr) return false;                        // 3D not initialised yet

    if (!state.pass) state.pass = new Cls();
    state.pass._runtimeScene = runtimeScene;

    // Already in this layer's chain? The composer is rebuilt when a scene
    // reloads, so verify the pass is still actually in it.
    if (state.attachedRenderer === lr) {
      let stillThere = false;
      try {
        const comp = lr.getThreeEffectComposer && lr.getThreeEffectComposer();
        stillThere = !!(comp && comp.passes && comp.passes.indexOf(state.pass) !== -1);
      } catch (e) { stillThere = false; }
      if (stillThere) {
        state.pass._layerRenderer = lr;
        applySceneBackground(state.pass, runtimeScene, lr);
        return true;
      }
      state.attachedRenderer = null;
    } else if (state.attachedRenderer) {
      detach();
    }

    try {
      lr.addPostProcessingPass(state.pass);
      state.attachedRenderer = lr;
      state.attachedLayerName = layerName || '';
      // The pass needs this at render() time to re-assert the backdrop.
      state.pass._layerRenderer = lr;
      applySceneBackground(state.pass, runtimeScene, lr);
      return true;
    } catch (e) {
      return false;
    }
  };

  // GDevelop assigns threeScene.background only on the FIRST layer it renders.
  // When a 2D layer renders first, the 3D layer gets background === null and
  // the backdrop lives only in PIXI's canvas clear -- the composer's RenderPass
  // would then clear to whatever colour was last set, and a white background
  // reads black. Keep the renderer's clear colour on the scene's own
  // background, exactly as GDevelop does for the first 3D layer.
  const syncClearColor = (runtimeScene) => {
    try {
      const gr = runtimeScene.getGame().getRenderer();
      const three = gr && gr.getThreeRenderer && gr.getThreeRenderer();
      if (!three || typeof runtimeScene.getBackgroundColor !== 'function') return;
      three.setClearColor(runtimeScene.getBackgroundColor(), 1);
    } catch (e) {}
  };

  // ===================================================================
  // PUBLIC API  (camelCase JS internals; the extension's PascalCase
  // actions/conditions/expressions wrap these.)
  // ===================================================================
  gdjs._crtLottes3D = {
    settings,
    DEFAULTS,

    // --- lifecycle ----------------------------------------------------
    // The pass is inserted into the target layer's own EffectComposer, the
    // same chain GDevelop's built-in 3D effects use. Nothing global is
    // patched, so other layers and other extensions are untouched.
    startEffect(runtimeScene, layer3D) {
      settings.enabled = true;
      if (layer3D !== undefined) settings.targetLayerName = layer3D || '';
      syncClearColor(runtimeScene);
      return attach(runtimeScene, settings.targetLayerName);
    },

    stopEffect(runtimeScene) {
      settings.enabled = false;
      // Pull the pass back out: with it removed, hasPostProcessingPass()
      // goes false again and GDevelop returns the layer to its plain
      // render path, exactly as if the extension had never run.
      detach();
    },

    isEnabled(runtimeScene) {
      return !!(settings.enabled && state.attachedRenderer);
    },

    // Called by the behavior every frame. 3D initialises lazily, so this
    // keeps retrying until the layer's composer exists, and re-inserts the
    // pass if a scene reload rebuilt the chain.
    tick(runtimeScene, layer3D) {
      if (layer3D !== undefined) settings.targetLayerName = layer3D || '';
      if (!settings.enabled) { detach(); return false; }
      syncClearColor(runtimeScene);
      return attach(runtimeScene, settings.targetLayerName);
    },

    dispose(runtimeScene) {
      detach();
      if (state.pass) { try { state.pass.dispose(); } catch (e) {} }
      state.pass = null;
    },

    setBool(name, value) {
      if (Object.prototype.hasOwnProperty.call(DEFAULTS, name)) settings[name] = !!value;
    },

    // --- Overlay layer (the called 2D layer, e.g. a HUD) -------------
    renderOverlayLayer(runtimeScene, layerName) {
      settings.overlayLayerName = layerName || '';
      settings.enOverlay = !!settings.overlayLayerName;
      // Stamp the scene now too, so the action works even on a scene that has
      // no 3DCRT+ behavior object driving tick().
      if (state.pass) state.pass._runtimeScene = runtimeScene;
      // [DEV WARN] If the chosen layer sits at/above the 3D layer in the list,
      // GDevelop draws it raw on top of the quad and the HUD escapes the effect
      // (the exact bug this feature prevents). Needs the scene's layer-order
      // accessor to compare indices; emit one console.warn once that's
      // confirmed. Left unwired rather than guessing a method name.
    },
    stopOverlayLayer(runtimeScene) {
      settings.enOverlay = false;
    },
    setOverlayOpacity(runtimeScene, v) {
      settings.overlayOpacity = Math.min(Math.max(v, 0), 1);
    },
    setOverlayGlow(runtimeScene, v) {
      settings.overlayGlow = Math.max(v, 0);
    },

    // ------------------------------------------------------------------
    // GROUP ENABLE FLAGS
    // Each effect group is switched on/off by name. Off = the group's
    // block is skipped in the shader (neutral), no matter its values.
    // Valid groups: Scanlines, Bulge, Border, Mask, Brightness, Bloom,
    // Aberration, Roll, Flicker, Interlace, Color.
    // ------------------------------------------------------------------
    _groupKey(group) {
      var key = 'en' + group;
      return Object.prototype.hasOwnProperty.call(DEFAULTS, key) ? key : null;
    },
    setGroupEnabled(rs, group, on) {
      var key = this._groupKey(group);
      if (key) settings[key] = !!on;
    },
    isGroupEnabled(rs, group) {
      var key = this._groupKey(group);
      return key ? !!settings[key] : false;
    },

    // ------------------------------------------------------------------
    // SCALE CONVERSIONS
    // The public actions/behavior speak in FRIENDLY units; these helpers
    // convert to/from the shader's internal units. Keeping the conversion
    // here (not in the shader) means the risky shader code is untouched.
    //
    //   opacity:        friendly 0..255   <-> internal 0..1
    //   scanlineThick:  friendly 0..100   <-> internal hardScan -4..-16
    //   pixelSharp:     friendly 0..100   <-> internal hardPix  -2..-6
    //   border:         friendly 0..45    <-> internal 0..0.45
    //   flicker:        friendly 0..20    <-> internal 0..0.2
    //   bloom:          friendly 0..100   <-> internal 0..1
    //   maskDark:       friendly 0..100   <-> internal 0..1
    // ------------------------------------------------------------------
    _clamp(v, lo, hi) { return Math.min(Math.max(v, lo), hi); },

    // --- master opacity (0-255) ---
    setOpacity(rs, v) { settings.intensity = this._clamp(v, 0, 255) / 255; },
    getOpacity() { return Math.round(settings.intensity * 255); },

    // --- scanlines: friendly "bigger = more" ---
    setScanlineThickness(rs, v) {
      v = this._clamp(v, 0, 100);
      settings.scanlineHardness = -4 - (v / 100) * 12; // 0->-4 soft, 100->-16 hard
    },
    getScanlineThickness() {
      return Math.round(((-4 - settings.scanlineHardness) / 12) * 100);
    },
    setPixelSharpness(rs, v) {
      v = this._clamp(v, 0, 100);
      settings.pixelHardness = -2 - (v / 100) * 4; // 0->-2 soft, 100->-6 sharp
    },
    getPixelSharpness() {
      return Math.round(((-2 - settings.pixelHardness) / 4) * 100);
    },
    setScanlineCount(rs, v) { settings.scanlineCount = Math.max(Math.round(v), 0); },
    getScanlineCount() { return settings.scanlineCount; },
    setPixelSize(rs, v) { settings.pixelSize = Math.max(v, 1); },
    getPixelSize() { return settings.pixelSize; },

    // --- shape ---
    setScreenBulge(rs, v) { settings.screenBulge = Math.max(v, 0); },
    getScreenBulge() { return settings.screenBulge; },
    setBorder(rs, v) { settings.border = this._clamp(v, 0, 45) / 100; },     // 0-45 -> 0-0.45 (master, all sides)
    getBorder() { return Math.round(settings.border * 100); },
    // Per-side EXTRA inset, friendly 0-45 -> internal 0-0.45, added on top of
    // the master border for that side. 0 => that side uses the master only.
    setBorderLeft(rs, v) { settings.borderLeft = this._clamp(v, 0, 45) / 100; },
    getBorderLeft() { return Math.round(settings.borderLeft * 100); },
    setBorderRight(rs, v) { settings.borderRight = this._clamp(v, 0, 45) / 100; },
    getBorderRight() { return Math.round(settings.borderRight * 100); },
    setBorderTop(rs, v) { settings.borderTop = this._clamp(v, 0, 45) / 100; },
    getBorderTop() { return Math.round(settings.borderTop * 100); },
    setBorderBottom(rs, v) { settings.borderBottom = this._clamp(v, 0, 45) / 100; },
    getBorderBottom() { return Math.round(settings.borderBottom * 100); },

    // --- image stretch (friendly percent 25-400, 100 = unchanged) ---
    setImageStretchX(rs, v) { settings.stretchX = this._clamp(v, 25, 400) / 100; },
    getImageStretchX() { return Math.round(settings.stretchX * 100); },
    setImageStretchY(rs, v) { settings.stretchY = this._clamp(v, 25, 400) / 100; },
    getImageStretchY() { return Math.round(settings.stretchY * 100); },

    // --- shadow mask ---
    setShadowMaskDarkLevel(rs, v) { settings.shadowMaskDarkLevel = this._clamp(v, 0, 100) / 100; }, // 0-100 -> 0-1
    getShadowMaskDarkLevel() { return Math.round(settings.shadowMaskDarkLevel * 100); },
    setShadowMaskLightLevel(rs, v) { settings.shadowMaskLightLevel = v; },
    getShadowMaskLightLevel() { return settings.shadowMaskLightLevel; },

    // --- tone ---
    setBrightness(rs, v) { settings.brightness = v; },
    getBrightness() { return settings.brightness; },
    setBloom(rs, v) { settings.bloom = Math.max(v, 0) / 100; },
    getBloom() { return Math.round(settings.bloom * 100); },
    setBloomThreshold(rs, v) { settings.bloomThreshold = this._clamp(v, 0, 200) / 100; }, // friendly 0-200 -> 0.0-2.0
    getBloomThreshold() { return Math.round(settings.bloomThreshold * 100); },
    setBloomRadius(rs, v) { settings.bloomRadius = this._clamp(v, 1, 50); }, // friendly 1-50 -> 1.0-50.0
    getBloomRadius() { return Math.round(settings.bloomRadius); },
    setBloomKnee(rs, v) { settings.bloomKnee = this._clamp(v, 0, 100) / 100; }, // friendly 0-100 -> 0.0-1.0
    getBloomKnee() { return Math.round(settings.bloomKnee * 100); },
    setBloomTint(rs, r, g, b) { settings.bloomTintR = Math.max(r, 0); settings.bloomTintG = Math.max(g, 0); settings.bloomTintB = Math.max(b, 0); },
    getBloomTintR() { return settings.bloomTintR; },
    getBloomTintG() { return settings.bloomTintG; },
    getBloomTintB() { return settings.bloomTintB; },

    // --- Softness prepass -------------------------------------------
    // Blur is friendly 0-100 -> 0..16 px radius. PixelateSize is already
    // in real pixels, so it passes through with a clamp only.
    setBlur(rs, v) { settings.blurAmount = this._clamp(v, 0, 100) / 100 * 16; },
    getBlur() { return Math.round(settings.blurAmount / 16 * 100); },
    setPixelateSize(rs, v) { settings.pixelateSize = this._clamp(v, 1, 64); },
    getPixelateSize() { return Math.round(settings.pixelateSize); },

    // --- glitch ---
    setAberration(rs, v) { settings.aberration = Math.max(v, 0); },
    getAberration() { return settings.aberration; },
    setRollSpeed(rs, v) { settings.rollSpeed = v; },
    getRollSpeed() { return settings.rollSpeed; },
    setRollHeight(rs, v) { settings.rollHeight = this._clamp(v, 0, 1); },
    getRollHeight() { return settings.rollHeight; },
    setFlicker(rs, v) { settings.flicker = this._clamp(v, 0, 20) / 100; },    // 0-20 -> 0-0.2
    getFlicker() { return Math.round(settings.flicker * 100); },
    setInterlace(rs, v) { settings.interlace = this._clamp(v, 0, 1); },
    getInterlace() { return settings.interlace; },

    // --- color ---
    setSaturation(rs, v) { settings.saturation = Math.max(v, 0); },
    getSaturation() { return settings.saturation; },
    setContrast(rs, v) { settings.contrast = v; },
    getContrast() { return settings.contrast; },
    setGamma(rs, v) { settings.gamma = Math.max(v, 0.01); },
    getGamma() { return settings.gamma; },
    setTint(rs, r, g, b) { settings.tintR = r; settings.tintG = g; settings.tintB = b; },
    getTintR() { return settings.tintR; },
    getTintG() { return settings.tintG; },
    getTintB() { return settings.tintB; },

    // --- grain (animated noise) ---
    setGrainAmount(rs, v) { settings.grainAmount = this._clamp(v, 0, 100) / 100; }, // 0-100 -> 0-1
    getGrainAmount() { return Math.round(settings.grainAmount * 100); },
    setGrainSize(rs, v) { settings.grainSize = this._clamp(v, 1, 100); },           // pixels per cell
    getGrainSize() { return Math.round(settings.grainSize); },
    setGrainColor(rs, v) { settings.grainColor = this._clamp(v, 0, 100) / 100; },   // 0 mono -> 100 colour
    getGrainColor() { return Math.round(settings.grainColor * 100); },
    setGrainSpeed(rs, v) { settings.grainSpeed = this._clamp(v, 0, 100) / 100; },   // 0 frozen -> 100 fast
    getGrainSpeed() { return Math.round(settings.grainSpeed * 100); },
  };
}

var on = eventsFunctionContext.getArgument("Enable");
on = (on === true || on === "yes" || on === "true" || on === 1);
gdjs._crtLottes3D.setGroupEnabled(runtimeScene, eventsFunctionContext.getArgument("Effect"), on);

// Per-frame sync: opacity, each group's enable checkbox, the group's
// settings (through named setters so scale conversions apply), then tick.
if (!gdjs._crtLottes3D) return;
var object = (typeof objects !== 'undefined' && objects.length) ? objects[0] : null;
if (!object) return;
var behaviorName = eventsFunctionContext.getBehaviorName("Behavior");
var behavior = object.getBehavior(behaviorName);
if (!behavior) return;
try {
  gdjs._crtLottes3D.setBool('enabled', true);
    gdjs._crtLottes3D.setOpacity(runtimeScene, behavior._getOpacity());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Scanlines", behavior._getEnableScanlines());
    gdjs._crtLottes3D.setScanlineThickness(runtimeScene, behavior._getScanlineThickness());
    gdjs._crtLottes3D.setPixelSharpness(runtimeScene, behavior._getPixelSharpness());
    gdjs._crtLottes3D.setScanlineCount(runtimeScene, behavior._getScanlineCount());
    gdjs._crtLottes3D.setPixelSize(runtimeScene, behavior._getPixelSize());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Bulge", behavior._getEnableBulge());
    gdjs._crtLottes3D.setScreenBulge(runtimeScene, behavior._getScreenBulge());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Border", behavior._getEnableBorder());
    gdjs._crtLottes3D.setBorder(runtimeScene, behavior._getBorder());
    gdjs._crtLottes3D.setBorderLeft(runtimeScene, behavior._getBorderLeft());
    gdjs._crtLottes3D.setBorderRight(runtimeScene, behavior._getBorderRight());
    gdjs._crtLottes3D.setBorderTop(runtimeScene, behavior._getBorderTop());
    gdjs._crtLottes3D.setBorderBottom(runtimeScene, behavior._getBorderBottom());
    gdjs._crtLottes3D.setImageStretchX(runtimeScene, behavior._getImageStretchX());
    gdjs._crtLottes3D.setImageStretchY(runtimeScene, behavior._getImageStretchY());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Mask", behavior._getEnableMask());
    gdjs._crtLottes3D.setShadowMaskDarkLevel(runtimeScene, behavior._getMaskDark());
    gdjs._crtLottes3D.setShadowMaskLightLevel(runtimeScene, behavior._getMaskLight());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Brightness", behavior._getEnableBrightness());
    gdjs._crtLottes3D.setBrightness(runtimeScene, behavior._getBrightness());
        gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Bloom", behavior._getEnableBloom());
    gdjs._crtLottes3D.setBloom(runtimeScene, behavior._getBloom());
    if (typeof behavior._getBloomThreshold === 'function') gdjs._crtLottes3D.setBloomThreshold(runtimeScene, behavior._getBloomThreshold());
    if (typeof behavior._getBloomRadius === 'function') gdjs._crtLottes3D.setBloomRadius(runtimeScene, behavior._getBloomRadius());
    if (typeof behavior._getBloomKnee === 'function') gdjs._crtLottes3D.setBloomKnee(runtimeScene, behavior._getBloomKnee());
    if (typeof behavior._getBloomTintR === 'function') gdjs._crtLottes3D.setBloomTint(runtimeScene, behavior._getBloomTintR(), behavior._getBloomTintG(), behavior._getBloomTintB());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Aberration", behavior._getEnableAberration());
    gdjs._crtLottes3D.setAberration(runtimeScene, behavior._getAberration());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Roll", behavior._getEnableRoll());
    gdjs._crtLottes3D.setRollSpeed(runtimeScene, behavior._getRollSpeed());
    gdjs._crtLottes3D.setRollHeight(runtimeScene, behavior._getRollHeight());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Flicker", behavior._getEnableFlicker());
    gdjs._crtLottes3D.setFlicker(runtimeScene, behavior._getFlicker());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Interlace", behavior._getEnableInterlace());
    gdjs._crtLottes3D.setInterlace(runtimeScene, behavior._getInterlace());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Color", behavior._getEnableColor());
    gdjs._crtLottes3D.setSaturation(runtimeScene, behavior._getSaturation());
    gdjs._crtLottes3D.setContrast(runtimeScene, behavior._getContrast());
    gdjs._crtLottes3D.setGamma(runtimeScene, behavior._getGamma());
    gdjs._crtLottes3D.setTint(runtimeScene, behavior._getTintR(), behavior._getTintG(), behavior._getTintB());
    gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Grain", behavior._getEnableGrain());
    gdjs._crtLottes3D.setGrainAmount(runtimeScene, behavior._getGrainAmount());
    gdjs._crtLottes3D.setGrainSize(runtimeScene, behavior._getGrainSize());
    gdjs._crtLottes3D.setGrainColor(runtimeScene, behavior._getGrainColor());
