    if (typeof behavior._getBlur === 'function') gdjs._crtLottes3D.setBlur(runtimeScene, behavior._getBlur());
    if (typeof behavior._getEnablePixelate === 'function') gdjs._crtLottes3D.setGroupEnabled(runtimeScene, "Pixelate", behavior._getEnablePixelate());
    if (typeof behavior._getPixelateSize === 'function') gdjs._crtLottes3D.setPixelateSize(runtimeScene, behavior._getPixelateSize());
